<?php
declare(strict_types=1);
ini_set('display_errors','0');require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/publication/core.php';require dirname(__DIR__).'/private/publication/media.php';security_headers();header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('Content-Type: application/json; charset=utf-8');
try{pub_gate();$mode=$_GET['mode']??'public';$r=$_GET['r']??'items';$method=$_SERVER['REQUEST_METHOD'];$a=null;
 if($mode==='owner'){current_session($method!=='GET');$a=['type'=>'owner','id'=>1];}
 elseif($mode==='customer'){$a=cc_actor(true,$method!=='GET');}
 elseif($mode==='prospect'){$s=ps_session($method!=='GET');$a=['type'=>'prospect','id'=>(int)$s['link_id'],'order_id'=>(int)$s['order_id'],'customer_id'=>(int)$s['customer_id'],'session'=>$s];}
 elseif($mode!=='public'||$method!=='GET')crm_fail(403,'Доступ запрещён.');rate('publications:'.$mode,180);
 if($method==='GET'){
  if($r==='items'){if(!in_array($mode,['owner','public'],true))crm_fail(404,'Раздел недоступен.');$kind=$_GET['kind']??'portfolio';if(!in_array($kind,['portfolio','review'],true))crm_fail(422,'Выберите раздел.');$rows=crm_query('SELECT * FROM nd_publications WHERE kind=?'.($mode==='public'?" AND state='PUBLISHED'":'').' ORDER BY sort_order,id DESC LIMIT 200',[$kind])->fetchAll();$items=[];foreach($rows as $p){$v=$mode==='public'?pub_version((int)$p['published_version_id']):pub_head($p);if($mode==='public'&&!pub_live($p,$v))continue;if($mode==='public')$items[]=['id'=>(int)$p['id'],'slug'=>$p['slug'],'body'=>$v['body'],'checksum'=>$v['checksum']];elseif($mode==='owner'){$p['head']=$v;$p['permissions']=crm_query('SELECT g.*,v.checksum FROM nd_publication_permissions g JOIN nd_publication_versions v ON v.id=g.version_id WHERE v.publication_id=? ORDER BY g.id DESC',[$p['id']])->fetchAll();$items[]=$p;}else crm_fail(404,'Раздел недоступен.');}json_response(['ok'=>true,'items'=>$items]);}
  if($r==='orders'&&$mode==='owner')json_response(['ok'=>true,'items'=>crm_query("SELECT o.id,CONCAT(o.number,' — ',o.title,' · ',c.name) AS label FROM nd_orders o JOIN nd_customers c ON c.id=o.customer_id WHERE o.archived_at IS NULL ORDER BY o.id DESC LIMIT 500")->fetchAll()]);
  if($r==='documents'&&$mode==='owner')json_response(['ok'=>true,'items'=>crm_query("SELECT b.id,t.title,b.state,t.kind FROM nd_lc_document_bindings b JOIN nd_lc_templates t ON t.id=b.template_id WHERE b.order_id=? AND t.kind IN ('portfolio_permission','review_permission') ORDER BY b.id DESC",[(int)($_GET['order']??0)])->fetchAll()]);
  if($r==='version'&&$mode==='owner'){$v=pub_version((int)($_GET['version']??0));$p=pub_record((int)$v['publication_id']);$reference='SHA-256 '.$v['checksum'];$values=['permission.version'=>$reference,'permission.material_list'=>$v['body']['title']."\n".$v['body']['text'],'permission.attachment_list'=>lc_json($v['body']['media']),'review.photo_reference'=>lc_json($v['body']['media']),'permission.channels'=>'https://neurodelo.pro/portfolio.php','permission.scope'=>'Только точная редакция '.$reference,'review.text'=>$v['body']['text'],'review.display_name'=>$v['body']['display_name'],'review.publication_terms'=>'Публикация точной редакции '.$reference.' на https://neurodelo.pro/reviews.php; отказ и отзыв не влияют на исполнение заказа.'];json_response(['ok'=>true,'version'=>$v,'kind'=>$p['kind'],'order_id'=>$p['order_id'],'values'=>$values]);}
  if($r==='media-list'&&$mode==='owner')json_response(['ok'=>true,'items'=>crm_query('SELECT id,display_name,mime,size_bytes,checksum FROM nd_publication_media ORDER BY id DESC LIMIT 200')->fetchAll()]);
  if($r==='review-orders'&&$a&&$mode!=='owner'){$where=$mode==='prospect'?' AND o.id=?':'';$params=[$a['customer_id']];if($mode==='prospect')$params[]=$a['order_id'];json_response(['ok'=>true,'items'=>crm_query("SELECT o.id,CONCAT(o.number,' — ',o.title) AS label FROM nd_orders o JOIN nd_lc_order_flow f ON f.order_id=o.id WHERE o.customer_id=? AND f.delivery_state IN ('HANDOVER_PREPARED','HANDED_OVER')".$where.' ORDER BY o.id DESC',$params)->fetchAll()]);}
  if($r==='permissions'&&$a){$rows=crm_query('SELECT g.* FROM nd_publication_permissions g'.($mode==='owner'?'':' WHERE g.customer_id=?').' ORDER BY g.id DESC LIMIT 200',$mode==='owner'?[]:[$a['customer_id']])->fetchAll();$out=[];foreach($rows as $g){try{pub_visible_permission($a,$g);}catch(CrmFailure $e){if($e->status===404)continue;throw $e;}$v=pub_version((int)$g['version_id']);$p=pub_record((int)$v['publication_id']);$out[]=['id'=>(int)$g['id'],'state'=>$g['state'],'kind'=>$p['kind'],'body'=>$v['body'],'checksum'=>$v['checksum'],'history'=>crm_query('SELECT action,reason,created_at FROM nd_publication_permission_events WHERE permission_id=? ORDER BY id',[$g['id']])->fetchAll()];}json_response(['ok'=>true,'items'=>$out]);}
  if($r==='media'){$id=(int)($_GET['id']??0);$file=crm_query('SELECT * FROM nd_publication_media WHERE id=?',[$id])->fetch();if(!$file)crm_fail(404,'Файл не найден.');$allow=$mode==='owner';if(!$allow&&$a){$g=crm_query('SELECT * FROM nd_publication_permissions WHERE id=?',[(int)($_GET['permission']??0)])->fetch();if($g){pub_visible_permission($a,$g);$v=pub_version((int)$g['version_id']);$allow=in_array($id,array_column($v['body']['media'],'id'),true);}}if(!$allow&&$mode==='public'){foreach(crm_query("SELECT * FROM nd_publications WHERE state='PUBLISHED'")->fetchAll() as $p){$v=pub_version((int)$p['published_version_id']);if(pub_live($p,$v)&&in_array($id,array_column($v['body']['media'],'id'),true)){$allow=true;break;}}}if(!$allow)crm_fail(404,'Файл не опубликован.');pub_stream($file);}
 }
 if($method==='POST'&&$a){$d=$r==='upload'?[]:input();if($r==='decide')json_response(pub_decide($a,$d));if($r==='review-submit')json_response(pub_review_submit($a,$d));cc_owner($a);$result=match($r){'save'=>pub_save($d),'publish'=>pub_publish($d,true),'unpublish'=>pub_publish($d,false),'request-permission'=>pub_request($d),'upload'=>pub_upload(),default=>throw new CrmFailure(404,'Действие не найдено.')};json_response($result);}crm_fail(404,'Раздел не найден.');
}catch(CrmFailure $e){fail($e->status,$e->getMessage(),'publication_error');}catch(CustomerFailure $e){fail($e->status,$e->getMessage(),$e->errorCode);}catch(PDOException $e){if($e->getCode()==='23000')fail(409,'Адрес или редакция уже существует. Обновите данные.','publication_conflict');server_error($e);}catch(Throwable $e){server_error($e);}
